"""Synthetic validation: data generated by a pure additive-floor model S_ih = f_h + s_i g_h (1 + eta_ih) with
s_i = s(k_i) (+ optional within-k jitter).  Checks what the adjusted regression and the floor simulation return."""
import sys, numpy as np
sys.path.insert(0, sys.argv[1]); sys.path.insert(0, sys.argv[1] + "/vet3")
from mass import topq, perm_idx, raw_z, adj_z
rng = np.random.default_rng(5); n, H = 252, 32; k = np.repeat(np.arange(1, 7), 42).astype(float); body = np.tile(np.arange(42), 6)
g = rng.lognormal(0, .8, H); g /= g.sum()
for jitter in [0.0, 0.15]:
    for ffrac, fshape in [(0.6, "uniform"), (0.6, "prop_to_g^0.3")]:
        f = np.ones(H) if fshape == "uniform" else g ** .3
        f = f / f.sum() * ffrac / (1 - ffrac)                 # floor mass = ffrac of layer mass at s=1
        s = (1 - .08 * (k - 1)) * np.exp(jitter * rng.standard_normal(n))
        S = f[None] + s[:, None] * g[None] * (1 + .25 * rng.standard_normal((n, H))).clip(0.05)
        S = S[:, None, :]; P = perm_idx(k, body, "pointer", np.random.default_rng(0))
        Y = topq(S); bY, zY = raw_z(Y, k, P); lM = np.log(S.sum(-1))
        ba, za = adj_z(Y, k, P, lambda l: lM[:, l:l+1])
        out = []
        for name, ff in [("true", f), ("min", S[:, 0].min(0)), ("worst", np.where(np.argsort(np.argsort(-S[:, 0].mean(0))) < 8, 0, S[:, 0].min(0)))]:
            u = np.clip(S - ff[None, None], 0, None); U = u.sum(-1, keepdims=True); C = u / U
            bp = np.mean([raw_z(topq(ff[None, None] + U * C[rng.permutation(n)]), k, P[:1])[0] for _ in range(40)], 0)
            out.append(f"{name} {bp[0]/bY[0]:.2f}")
        print(f"jitter {jitter} floor {ffrac} {fshape:14s}: raw z {zY[0]:+.2f}; adj_logM z {za[0]:+.2f} (remaining {ba[0]/bY[0]:.2f}); floor-sim predicted fraction: " + ", ".join(out))
